parso.python.diff._get_debug_error_messa:
def _get_debug_error_message(module, old_lines, new_lines):
    current_lines = split_lines(module.get_code(), keepends=True)
    current_diff = difflib.unified_diff(new_lines, current_lines)
    old_new_diff = difflib.unified_diff(old_lines, new_lines)
    import parso
    return "There's an issue with the diff parser. Please report (parso v%s) - Old/New:\n%s\nActual Diff (May be empty):\n%s" % (parso.__version__, ''.join(old_new_diff), ''.join(current_diff))

jedi.inference.docstrings.infer_param:
@inference_state_method_cache()
def infer_param(function_value, param):

    def infer_docstring(docstring):
        return ValueSet((p for param_str in _search_param_in_docstr(docstring, param.name.value) for p in _infer_for_statement_string(module_context, param_str)))
    module_context = function_value.get_root_context()
    func = param.get_parent_function()
    if func.type == 'lambdef':
        return NO_VALUES
    types = infer_docstring(function_value.py__doc__())
    if (function_value.is_bound_method() and function_value.py__name__() == '__init__'):
        types |= infer_docstring(function_value.class_context.py__doc__())
    debug.dbg('Found param types for docstring: %s', types, color='BLUE')
    return types

