jedi.parser_utils.get_signature:
def get_signature(funcdef, width=72, call_string=None, omit_first_param=False, omit_return_annotation=False):
    """
    Generate a string signature of a function.

    :param width: Fold lines if a line is longer than this value.
    :type width: int
    :arg func_name: Override function name when given.
    :type func_name: str

    :rtype: str
    """
    if call_string is None:
        if funcdef.type == 'lambdef':
            call_string = '<lambda>'
        else:
            call_string = funcdef.name.value
    params = funcdef.get_params()
    if omit_first_param:
        params = params[1:]
    p = '(' + ''.join((param.get_code() for param in params)).strip() + ')'
    p = re.sub('\\s+', ' ', p)
    if (funcdef.annotation and not omit_return_annotation):
        rtype = ' ->' + funcdef.annotation.get_code()
    else:
        rtype = ''
    code = call_string + p + rtype
    return '\n'.join(textwrap.wrap(code, width))

jedi.api.keywords.imitate_pydoc:
def imitate_pydoc(string):
    """
    It's not possible to get the pydoc's without starting the annoying pager
    stuff.
    """
    if pydoc_topics is None:
        return ''
    h = pydoc.help
    with suppress(KeyError):
        string = h.symbols[string]
        (string, _, related) = string.partition(' ')

    def get_target(s):
        return h.topics.get(s, h.keywords.get(s))
    while isinstance(string, str):
        string = get_target(string)
    try:
        (label, related) = string
    except TypeError:
        return ''
    try:
        return (pydoc_topics[label].strip() if pydoc_topics else '')
    except KeyError:
        return ''
